1	#!/usr/bin/env node
2	
3	import { mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
4	import { tmpdir } from "node:os";
5	import { join } from "node:path";
6	import { spawnSync } from "node:child_process";
7	
8	const version = process.env.WORKSPACEJSON_RELEASE_VERSION
9	  ?? JSON.parse(readFileSync(new URL("../packages/spec/package.json", import.meta.url), "utf8")).version;
10	// Only packages this repository publishes are verified here. `agents-audit` is
11	// published by workspacejson/cli and was deliberately removed during the
12	// extraction migration: per the four-repository ledger, no target repository
13	// verifies a package it does not publish.
14	//
15	// Two of these checks used to assert the opposite of what they meant, and both
16	// would only ever have fired AFTER publication — when the registry version is
17	// already permanent and nothing can be withdrawn:
18	//
19	//   * the spec binary has no `--help`. Its single command is `validate <file>`
20	//     and every other form exits 1 with usage, so `--help` asserted that the
21	//     published binary FAILS. It now does the binary's actual job, on the
22	//     smallest document the profile admits.
23	//   * `@workspacejson/rules/testing` re-exports vitest helpers, and vitest throws
24	//     "failed to access its internal state" when evaluated outside a vitest run.
25	//     So it is verified by RESOLUTION, not evaluation — the same distinction CI
26	//     makes. Its runtime behavior is covered by the package's own vitest suite.
27	//
28	// The document is written here rather than taken from packages/spec/examples/.
29	// The repository's examples track the CURRENT profile and legitimately move
30	// ahead of what is on the registry, so pairing one with an older published
31	// validator fails for a reason that has nothing to do with the release. This is
32	// the minimal shape the v0.4 profile requires — the four required root keys and
33	// nothing optional — so it stays valid across the whole 0.4 line.
34	const PROBE_DOCUMENT = {
35	  manual: {},
36	  generated: {
37	    specVersion: "0.4",
38	    generatedAt: "2026-01-01T00:00:00Z",
39	    by: { name: "workspacejson-release-verification", version: "1.0.0" },
40	  },
41	  agents: {},
42	  health: {},
43	};
44	
45	const packages = [
46	  { name: "@workspacejson/spec", check: ["npx", "--no-install", "workspacejson-spec", "validate", "probe.json"] },
47	  { name: "@workspacejson/rules", check: ["node", "--input-type=module", "-e", "import('@workspacejson/rules')"] },
48	  {
49	    name: "@workspacejson/rules",
50	    check: [
51	      "node",
52	      "--input-type=module",
53	      "-e",
54	      "const u = import.meta.resolve('@workspacejson/rules/testing');" +
55	        "if (!u.endsWith('/dist/testing/rule-tester.js')) throw new Error('unexpected ./testing resolution: ' + u);" +
56	        "console.log('@workspacejson/rules/testing resolves to ' + u);",
57	    ],
58	  },
59	];
60	
61	// npm registry propagation lags publish by seconds to low minutes. A single
62	// immediate post-publish check has no way to tell "not actually published"
63	// apart from "not visible here yet" and fails the Release workflow either
64	// way — training everyone to ignore red, which is worse than no gate at all.
65	//
66	// The budget is a DURATION, not an attempt count, because the attempt count is
67	// exactly what drifted away from the sentence above it. Six attempts with a
68	// linear five-second step is seventy-five seconds of waiting, which does not
69	// cover "low minutes" and did not cover the 0.5.0 release: both packages were
70	// published successfully at 00:05:31, the retries were exhausted at 00:06:48,
71	// and the same script passed against the same registry minutes later. The
72	// release was real; the receipt said otherwise.
73	//
74	// A count has to be mentally multiplied out before it can be compared to the
75	// claim. A duration cannot silently disagree with it.
76	const REGISTRY_PROPAGATION_BUDGET_MS = 10 * 60 * 1000;
77	const REGISTRY_PROPAGATION_BASE_DELAY_MS = 5000;
78	// Capped so the tail of a long wait stays responsive rather than sleeping for
79	// minutes past the moment the package actually appears.
80	const REGISTRY_PROPAGATION_MAX_DELAY_MS = 30000;
81	const isRegistryPropagationLag = (stderr) => /\bE(TARGET|404)\b|No matching version found/.test(stderr ?? "");
82	const seconds = (ms) => `${Math.round(ms / 1000)}s`;
83	
84	for (const pkg of packages) {
85	  const directory = mkdtempSync(join(tmpdir(), "workspacejson-registry-"));
86	  try {
87	    writeFileSync(join(directory, "package.json"), JSON.stringify({ private: true, type: "module" }));
88	    writeFileSync(join(directory, "probe.json"), JSON.stringify(PROBE_DOCUMENT, null, 2));
89	    await installWithRetry(pkg, directory);
90	    run(pkg.check[0], pkg.check.slice(1), directory);
91	    console.log(`Verified registry install and runtime entry point: ${pkg.name}@${version}`);
92	  } finally {
93	    rmSync(directory, { recursive: true, force: true });
94	  }
95	}
96	
97	async function installWithRetry(pkg, directory) {
98	  const startedAt = Date.now();
99	  for (let attempt = 1; ; attempt++) {
100	    const result = spawnSync("npm", ["install", "--ignore-scripts", "--no-package-lock", `${pkg.name}@${version}`], {
101	      cwd: directory,
102	      encoding: "utf8",
103	      env: { ...process.env, npm_config_cache: join(directory, ".npm-cache") },
104	    });
105	    if (result.status === 0) {
106	      process.stdout.write(result.stdout);
107	      if (attempt > 1) {
108	        console.log(`${pkg.name}@${version} became visible after ${seconds(Date.now() - startedAt)} (attempt ${attempt}).`);
109	      }
110	      return;
111	    }
112	
113	    const lag = isRegistryPropagationLag(result.stderr);
114	    const elapsedMs = Date.now() - startedAt;
115	    const exhausted = elapsedMs >= REGISTRY_PROPAGATION_BUDGET_MS;
116	
117	    if (!lag || exhausted) {
118	      process.stdout.write(result.stdout);
119	      process.stderr.write(result.stderr);
120	      if (lag) {
121	        // Say which of the two things this is, rather than leaving a reader to
122	        // infer a failed publish from a failed lookup. They are not the same
123	        // event and they need different responses.
124	        console.error(
125	          `\n${pkg.name}@${version} was still not visible after ${seconds(elapsedMs)}, which is the whole ` +
126	            `${seconds(REGISTRY_PROPAGATION_BUDGET_MS)} propagation budget.\n` +
127	            `This is NOT proof that publication failed. Check the registry directly before treating it as one:\n` +
128	            `  npm view ${pkg.name} versions\n` +
129	            `If ${version} is present, the package shipped and only this receipt is missing — re-run this script.\n` +
130	            `If it is absent, the publish did not land and the release needs to be re-cut.`,
131	        );
132	      }
133	      process.exit(result.status ?? 1);
134	    }
135	
136	    const delayMs = Math.min(REGISTRY_PROPAGATION_BASE_DELAY_MS * attempt, REGISTRY_PROPAGATION_MAX_DELAY_MS);
137	    console.log(
138	      `${pkg.name}@${version} not yet visible on the registry ` +
139	        `(attempt ${attempt}, ${seconds(elapsedMs)} of ${seconds(REGISTRY_PROPAGATION_BUDGET_MS)} elapsed) — retrying in ${delayMs}ms`,
140	    );
141	    await new Promise((resolve) => setTimeout(resolve, delayMs));
142	  }
143	}
144	
145	function run(command, args, cwd) {
146	  const result = spawnSync(command, args, {
147	    cwd,
148	    encoding: "utf8",
149	    env: { ...process.env, npm_config_cache: join(cwd, ".npm-cache") },
150	  });
151	  process.stdout.write(result.stdout);
152	  process.stderr.write(result.stderr);
153	  if (result.status !== 0) process.exit(result.status ?? 1);
154	}
